from pathlib import Path
import subprocess,json,shutil
r=Path.cwd()
def git(*a):return subprocess.check_output(['git',*a],text=True).strip()
audit=json.loads((r/'build/publication-audit113.json').read_text(encoding='utf8'));assert audit['passed'] and audit['remoteFetched']
release=git('rev-parse','readme-113^{commit}');assert release==audit['commit']==git('rev-parse','HEAD');tag=git('rev-parse','readme-113')
analysis=json.loads((r/'build/analysis113.json').read_text(encoding='utf8'));assert analysis['passed']
data={'edition':113,'releaseCommit':release,'annotatedTag':'readme-113','tagObject':tag,'audit':audit,'analysis':analysis,'releaseCI':json.loads((r/'build/ci113-release.json').read_text(encoding='utf8')),'scope':'Actual non-force main/edition113/tag push, fetched and audited. Unified original history, exact checked report opening, unchanged Java authority and capacity. Eight actual completions, one abrupt same-ID recovery, genuine bank24-to32, six cold UI/recheck measurements. CI separate.'}
(r/'docs/PUBLICATION_113.json').write_text(json.dumps(data,indent=2)+'\n',encoding='utf8')
folder=r/'docs/publication113';folder.mkdir(exist_ok=True)
names=['ci113-release.json','publication-audit113.json','push113.log','release113.log','release113.py','audit-publication113.py','publication113.py','finish-publication113.py','freeze113.py','check-guide113.cjs','visual113.json','visual-review113.json','documentation-check.json','doc-check113.log','guide113.log','guide113-1440.png','guide113-390.png','ci113-parent.json','analysis113.json','compile113.log','history113.log','inspect113.log','desktop113-final.log','history113-late-error-before.log','history113-final-ui.log','doc-check113-initial.log','desktop113.log','desktop113-initial.log','desktop113-additional.log','source-identity113.json']
for name in names:assert (r/'build'/name).is_file(),name;shutil.copyfile(r/'build'/name,folder/name)
notice=f"Published release {release}; annotated readme-113 tag object {tag}. Actual main/edition113/tag push fetched and verified: {audit['canonicalSourceFiles']} canonical sources, {audit['frozenHashes']} frozen hashes across113 editions and {audit['original113EvidenceFiles']} original archive entries. "
validation='165 desktop checks and20 altered-original refusals pass. Fresh Java install;347 production classes and54 resources byte-identical to112. Eight fresh requests,40 retained qualification-evidence rechecks, eight new selected-data workflows, one abrupt recovery,32 saved procedures.31/78/94 archived chats/workflows/steps and3 cancelled chats retained. Exact checked saved reports, six cold UI/recheck measurements and all costs preserved. Initial fixture failures retained. Actual screenshots, review and next-phase plan published. No model training or generic speedup claim. Preserve private worlds and frozen editions; no delegation. '
for name,link in [('AGENTS.md','docs/PUBLICATION_113.json'),('README-CONTRIBUTORS.md','docs/PUBLICATION_113.json'),('docs/PROJECT_MEMORY.md','PUBLICATION_113.json'),('docs/DEVELOPMENT_LOG.md','PUBLICATION_113.json'),('docs/ARCHITECTURE.md','PUBLICATION_113.json')]:
 p=r/name;s=p.read_text(encoding='utf8');assert '## Edition113 — validated unified experience history' in s;s=s.replace('## Edition113 — validated unified experience history','## Edition113 — published and fetched back\n\n'+notice+validation+'[Publication receipt]('+link+').',1).replace('Publication pending actual push/fetch; CI separate.','Main/tag publication and fetched verification completed; remote CI is recorded separately.',1);p.write_text(s,encoding='utf8',newline='\n')
p=r/'README.md';p.write_text(p.read_text(encoding='utf8')+'\nPublished to main. [Edition113 fetched GitHub verification](docs/PUBLICATION_113.json).\n',encoding='utf8',newline='\n')
p=r/'docs/obsidian/121-usable-experience-history.md';p.write_text(p.read_text(encoding='utf8').replace('Publication pending actual push/fetch; CI separate.','Publication and fetched verification completed; CI separate.')+'\n'+notice+validation+'[[docs/PUBLICATION_113.json|Publication receipt]]\n',encoding='utf8',newline='\n')
print(notice)
